// Basic fallback for Select2
(function($) {
    if (typeof $ !== 'undefined' && !$.fn.select2) {
        $.fn.select2 = function(options) {
            console.warn('Select2 library not loaded. Please download from https://select2.org/');
            return this;
        };
    }
})(window.jQuery || window.$);
